import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1788284319000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Almost always the tool filter rather than a bug. Check <code>WOODPECKER_ALLOW_TOOLS</code> and <code>WOODPECKER_DENY_TOOLS</code>, and check <code>WOODPECKER_READ_ONLY</code> — under read-only the 37 write tools are never registered, so they are absent from <code>tools/list</code> rather than failing when called. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>If neither is set, the tool may be one of the handful that deliberately do not exist: reading or rotating this server&#39;s own access token, the forge webhook endpoint, the pprof debug handlers, the SSE streams and the badge images. The <a href="/guide/">introduction</a> says why for each.</p><h2 id="everything-answers-401-but-the-token-is-right" tabindex="-1">Everything answers 401, but the token is right <a class="header-anchor" href="#everything-answers-401-but-the-token-is-right" aria-label="Permalink to “Everything answers 401, but the token is right”">​</a></h2><p>Call <code>get_server_info</code> — it works without a token. If it answers with a version, the URL is fine and the token really is the problem: personal access tokens are shown once and are per instance, so a token from a different Woodpecker looks exactly like a wrong one.</p><p>If <code>get_server_info</code> instead fails saying the answer was HTML, see the next question.</p><h2 id="it-says-woodpecker-answered-with-html-instead-of-json" tabindex="-1">It says Woodpecker answered with HTML instead of JSON <a class="header-anchor" href="#it-says-woodpecker-answered-with-html-instead-of-json" aria-label="Permalink to “It says Woodpecker answered with HTML instead of JSON”">​</a></h2><p><code>WOODPECKER_URL</code> is reaching a web page rather than the API. Woodpecker serves its web UI from the same origin as its API and falls back to the single-page app for anything it does not route — so a wrong path, a wrong host, or an SSO portal or reverse proxy in front of the instance answers <strong>HTTP 200 with HTML</strong>, not a 404. That is why this is a named error rather than a JSON parse failure.</p><p>Check that the URL is the one you open in a browser, without <code>/api</code> and without a path of its own. If it looks right and you are on a VPN or split-DNS network, see the DNS note under <a href="/guide/clients#docker">Docker</a> — a container resolving the name against a public resolver gets an address that never answers.</p><h2 id="a-repository-i-can-see-in-my-forge-answers-404" tabindex="-1">A repository I can see in my forge answers 404 <a class="header-anchor" href="#a-repository-i-can-see-in-my-forge-answers-404" aria-label="Permalink to “A repository I can see in my forge answers 404”">​</a></h2><p>Woodpecker only knows repositories that were <strong>activated</strong> in it. Until then it exists in the forge and not here, and every call by id or by name is a 404.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>list_repositories(include_inactive: true)   # lists them, with forge_remote_id</span></span>
<span class="line"><span>activate_repository(forge_remote_id: &quot;…&quot;)   # turns one on</span></span></code></pre></div><p>Note that <code>activate_repository</code> takes the <strong>forge-side</strong> id, not a Woodpecker <code>repo_id</code> — there is no Woodpecker id yet — and not an <code>owner/name</code> pair.</p><h2 id="the-log-is-empty-or-it-is-the-wrong-end-of-it" tabindex="-1">The log is empty, or it is the wrong end of it <a class="header-anchor" href="#the-log-is-empty-or-it-is-the-wrong-end-of-it" aria-label="Permalink to “The log is empty, or it is the wrong end of it”">​</a></h2><p><code>get_step_logs</code> returns the <strong>last</strong> 200 lines by default, because that is where a failing step explains itself. Pass <code>from: &quot;head&quot;</code> for the beginning and <code>limit</code> for more; the result always says which window you got and how many lines exist.</p><p>An empty result usually means the step never ran — a skipped step, or one whose <code>when:</code> condition did not match. <code>get_pipeline</code> shows each step&#39;s state.</p><h2 id="a-secret-exists-but-the-pipeline-does-not-see-it" tabindex="-1">A secret exists, but the pipeline does not see it <a class="header-anchor" href="#a-secret-exists-but-the-pipeline-does-not-see-it" aria-label="Permalink to “A secret exists, but the pipeline does not see it”">​</a></h2><p>Three usual causes, in order of how often they are the answer:</p><ol><li><strong>Events.</strong> A secret applies only to the events it names, and the API has no defaults — a secret created without <code>pull_request</code> is invisible to pull-request builds. <code>get_secret</code> shows the list.</li><li><strong>Images.</strong> A non-empty <code>images</code> list restricts the secret to those container images. An empty list means every image, which is what most people want.</li><li><strong>Scope.</strong> Secrets exist at repository, organization and instance level, and <code>list_secrets</code> shows one level at a time. A name missing from the repository level may well exist one level up.</li></ol><h2 id="my-cron-job-runs-at-the-wrong-time-or-not-at-all" tabindex="-1">My cron job runs at the wrong time, or not at all <a class="header-anchor" href="#my-cron-job-runs-at-the-wrong-time-or-not-at-all" aria-label="Permalink to “My cron job runs at the wrong time, or not at all”">​</a></h2><p>Woodpecker takes a <strong>five-field</strong> cron expression — minute, hour, day of month, month, day of week — plus the <code>@daily</code>-style descriptors and <code>@every 30m</code>. It is not the six-field form with a leading seconds field that some Go schedulers use, so a schedule copied from one of those is off by a field.</p><p>Also check that the job is <code>enabled</code>, and remember the pipeline runs with event <code>cron</code>: steps restricted to <code>push</code> are skipped, which looks like a job that runs and does nothing.</p><h2 id="setting-a-cron-timezone-fails-with-unknown-time-zone" tabindex="-1">Setting a cron timezone fails with &quot;unknown time zone&quot; <a class="header-anchor" href="#setting-a-cron-timezone-fails-with-unknown-time-zone" aria-label="Permalink to “Setting a cron timezone fails with &quot;unknown time zone&quot;”">​</a></h2><p>Not a typo. Woodpecker resolves the zone with Go&#39;s <code>time.LoadLocation</code>, which reads the system zoneinfo database — and the official <code>woodpeckerci/woodpecker-server</code> image is distroless and ships none. On a stock Docker deployment every zone except <code>UTC</code> is rejected:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>can&#39;t parse timezone: unknown time zone Europe/Berlin</span></span></code></pre></div><p>Either leave the timezone at its default of UTC and write the schedule in UTC, or mount a zoneinfo database into the server container (<code>-v /usr/share/zoneinfo:/usr/share/zoneinfo:ro</code>). Verified against 3.18.0.</p><h2 id="why-can-it-not-restart-a-pipeline-i-just-deleted" tabindex="-1">Why can it not restart a pipeline I just deleted? <a class="header-anchor" href="#why-can-it-not-restart-a-pipeline-i-just-deleted" aria-label="Permalink to “Why can it not restart a pipeline I just deleted?”">​</a></h2><p>Deleting a pipeline takes its logs and step results with it; there is nothing left to re-run. That is why <code>delete_pipeline</code> <a href="/guide/approval">asks a person</a>. If you only want it to stop, <code>cancel_pipeline</code> is the reversible one.</p><h2 id="can-i-use-this-against-a-woodpecker-behind-sso" tabindex="-1">Can I use this against a Woodpecker behind SSO? <a class="header-anchor" href="#can-i-use-this-against-a-woodpecker-behind-sso" aria-label="Permalink to “Can I use this against a Woodpecker behind SSO?”">​</a></h2><p>Only if the API path is reachable without the SSO redirect. Personal access tokens authenticate against the API directly, but a proxy that intercepts every request and returns a login page will produce the HTML error above. Exempting <code>/api</code> from the SSO rule is the usual fix.</p>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};